92	func (pm *PathModel) statusLine() components.Status {
93		if pm.errText != "" {
94			return components.Status{Text: pm.errText, Level: components.LevelError}
95		}
96		if pm.state != pathRunning {
97			return components.Status{}
98		}
99		host := pm.target.Host
100		n := pm.hopCount()
101		if !pm.addr.IsValid() && n == 0 {
102			return components.Status{Text: "Resolving " + host + "...", Activity: true}
103		}
104		where := host
105		if pm.addr.IsValid() && pm.addr.String() != host {
106			where += " (" + pm.addr.String() + ")"
107		}
108		noun := "hops"
109		if n == 1 {
110			noun = "hop"
111		}
112		return components.Status{
113			Text:     fmt.Sprintf("Tracing %s — %d %s answered", where, n, noun),
