//     runes "alt+:".
//
// For several characters typed in a row, use Type; for a bracketed paste, Paste.
//
// Under bubbletea v2 the space key's String() is "space"; production code
// matches it as keymap.Space and never as a literal.
func Key(name string) tea.KeyPressMsg {
	if rest, isAlt := strings.CutPrefix(name, "alt+"); isAlt && rest != "" {
		msg := Key(rest)
		msg.Mod |= tea.ModAlt
		msg.Text = ""
		return msg
	}
	if name == " " || name == "space" {
		return spaceKey()
	}
	if name == "shift+tab" {
		return tea.KeyPressMsg{Code: tea.KeyTab, Mod: tea.ModShift}
	}
	if code, ok := namedKeys[name]; ok {
		return tea.KeyPressMsg{Code: code}
	}
	if letter, ok := strings.CutPrefix(name, "ctrl+"); ok && len(letter) == 1 && letter[0] >= 'a' && letter[0] <= 'z' {
		return tea.KeyPressMsg{Code: rune(letter[0]), Mod: tea.ModCtrl}
	}
	if r := []rune(name); len(r) == 1 {
		return tea.KeyPressMsg{Code: r[0], Text: name}
	}
	panic(fmt.Sprintf("testutil.Key: unknown key name %q (use Type for several characters, Paste for a paste)", name))
}

// Keys builds one message per name, for feeding a sequence to Update().
	}
	return shortcut.Shortcut{}, false
}

// Paste builds the message a bracketed paste of s delivers: one PasteMsg
// carrying the whole text.
func Paste(s string) tea.Msg {
	return tea.PasteMsg{Content: s}
}

// IsText reports whether msg carries text a text input would insert: a key
// press with text and no ctrl/alt modifier, or a paste.
func IsText(msg tea.Msg) bool {
	_, ok := Text(msg)
	return ok
}

// Text returns the text msg carries, typed or pasted, and whether msg is such
// a message.
func Text(msg tea.Msg) (string, bool) {
	switch m := msg.(type) {

// containerText is the Address cell of the container row.
func (c pathContainer) containerText() string {
	switch {
	case c.Known && !c.Running:
		return c.Name + " (" + textNotRunning + ")"
	case c.Attach == attachNetwork && c.Addr.IsValid():
		return c.Name + " (" + c.Addr.String() + ")"
	}
	return c.Name
}

// networkText is the Address cell of the network row.
func (c pathContainer) networkText() string {
	switch c.Attach {
	case attachNetwork:
		if c.Gateway.IsValid() {
			return c.Network + " via " + c.Gateway.String()
		}
		return c.Network
	case attachHost:
		return textHostNetwork
	case attachNone:
		return textNoNetwork
	case attachShared:
		return textSharedNetwork
	}
	if c.Networks > 1 {
		return fmt.Sprintf("%s (%d networks)", textUndetermined, c.Networks)
	}
	return textUndetermined
}

// traceText is the Address cell of the trace row.
func (c pathContainer) traceText() string {
	if c.Attach == attachHost {
		return textTraceSharedHost
	}
	return textTraceFromHost
}

// dimNetwork reports whether the network row says nothing about a path.
func (c pathContainer) dimNetwork() bool {
	return c.Attach == attachUndetermined || c.Attach == attachNone
}
